export const TREE_SPECIES_RESEARCH = Object.freeze(Object.fromEntries(
  Object.entries(RECORDS).map(([id, record]) => [
    id,
    Object.freeze({
      ...record,
      referenceSources: Object.freeze([
        record.powoUrl,
        record.summaryUrl,
        record.referenceImagePageUrl,
      ].filter(Boolean)),
    }),
  ]),
));
